// Keep items from the last 26h (2h overlap so a late run never drops items).
// Per-feed caps and short snippets keep the prompt small (about 10k tokens); the gateway rejects prompts that are too large.
const WINDOW_MS = 26 * 60 * 60 * 1000;
const CAP = 12;
const ARXIV_CAP = 15; // arXiv dates are daily batches, so skip the date filter
const cutoff = Date.now() - WINDOW_MS;
const count = {};
const out = { technical: [], world: [] };

const all = $input.all();
for (let i = 0; i < all.length; i++) {
  const j = all[i].json;
  if (j.error || !j.title) continue; // failed feed or empty entry
  // pairedItem.item is the item's index in this node's own input, so trace back to the feed
  // through n8n's item linking instead of indexing Feed List directly
  let feed;
  try { feed = $('Feed List').itemMatching(i).json; } catch (e) { feed = null; }
  if (!feed) continue;

  const source = (feed.url.match(/^https?:\/\/(?:www\.)?([^\/]+)/) || [])[1] || feed.url;
  const isArxiv = source.includes('arxiv');
  const ts = Date.parse(j.isoDate || j.pubDate || '');
  if (!isArxiv && !Number.isNaN(ts) && ts < cutoff) continue;

  count[feed.url] = (count[feed.url] || 0) + 1;
  if (count[feed.url] > (isArxiv ? ARXIV_CAP : CAP)) continue;

  const text = (j.contentSnippet || j.content || j.summary || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 220);

  out[feed.category].push({
    title: j.title,
    source,
    url: j.link,
    published: j.isoDate || j.pubDate || null,
    snippet: text,
  });
}
// Fail loudly: an empty digest from broken ingestion must not look like a quiet news day
const failed = all.filter((x) => x.json.error).length;
if (!out.technical.length && !out.world.length) {
  throw new Error('No articles passed filtering. RSS items: ' + all.length + ', failed feeds: ' + failed);
}
return [{ json: out }];

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

// The agent returns plain JSON text (no tool-calling), possibly wrapped in code fences
let d = $json.output;
if (typeof d === 'string') {
  const s = d.replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
  try {
    d = JSON.parse(s);
  } catch (e) {
    const m = s.match(/\{[\s\S]*\}/);
    try { d = m ? JSON.parse(m[0]) : null; } catch (e2) { d = null; }
  }
}
if (!d || typeof d !== 'object') {
  throw new Error('Agent did not return valid JSON: ' + String($json.output).slice(0, 300));
}

const date = new Date().toLocaleDateString('en-IN', { timeZone: 'Asia/Kolkata', weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' });

const section = (title, groups = []) => {
  if (!groups.length) return `<h2>${title}</h2><p style="color:#666">Nothing important today.</p>`;
  const body = groups.map((g) => `
    <h3 style="margin:18px 0 6px;color:#333">${esc(g.topic ?? g.heading)}</h3>
    ${(g.items || []).map((it) => `
      <div style="margin:0 0 14px;padding-left:10px;border-left:3px solid #ddd">
        <a href="${esc(it.url)}" style="font-weight:600;color:#1a56db;text-decoration:none">${esc(it.title)}</a>
        <span style="color:#888;font-size:12px"> · ${esc(it.source)}${it.importance ? ` · ${'★'.repeat(Math.min(5, Math.max(1, it.importance)))}` : ''}</span>
        <div style="margin-top:3px">${esc(it.summary)}</div>
        ${it.why_it_matters ? `<div style="margin-top:3px;color:#555"><em>Why it matters:</em> ${esc(it.why_it_matters)}</div>` : ''}
      </div>`).join('')}`).join('');
  return `<h2 style="border-bottom:2px solid #222;padding-bottom:4px">${title}</h2>${body}`;
};

const st = d.statistics;
const stats = st ? `<p style="color:#888;font-size:12px;margin-top:24px">Received ${esc(st.total_received)} · selected ${esc(st.total_selected)} · merged ${esc(st.total_merged)} · discarded ${esc(st.total_discarded)}</p>` : '';
const tldr = (d.tldr || []).map((t) => `<li>${esc(t)}</li>`).join('');
const html = `<div style="font-family:Arial,sans-serif;max-width:680px;margin:auto;line-height:1.5;color:#111">
  <h1 style="margin-bottom:0">Daily Digest</h1><div style="color:#888">${date}</div>
  <h2>TL;DR</h2><ul>${tldr}</ul>
  ${section('Technical', d.technical)}
  ${section('World News', d.world)}
  ${stats}
</div>`;
return [{ json: { subject: `Daily Digest · ${date}`, html } }];
